
// Supabase public features: repair status lookup, moderated reviews and reminders.
(() => {
 const URL='https://vxglqhgvtoxtcqydalpe.supabase.co';
 const KEY='sb_publishable_rbOQzEL4BSyEBjE8LzQbDQ_m-KN6Wiq';
 const headers={'apikey':KEY,'Authorization':'Bearer '+KEY,'Content-Type':'application/json'};
 const message=(id,text,ok=false)=>{const el=document.getElementById(id);if(el){el.textContent=text;el.dataset.state=ok?'success':'error';}};
 const lookup=document.getElementById('repair-lookup-form');
 if(lookup) lookup.addEventListener('submit',async e=>{e.preventDefault();const code=new FormData(lookup).get('code').trim().toUpperCase();message('repair-lookup-result','Se verifică...');try{const r=await fetch(URL+'/rest/v1/rpc/lookup_repair_status',{method:'POST',headers,body:JSON.stringify({p_code:code})});if(!r.ok)throw new Error(await r.text());const rows=await r.json();if(!rows.length){message('repair-lookup-result','Nu am găsit o lucrare pentru acest cod. Verifică-l sau contactează service-ul.');return;}const row=rows[0];const labels={new:'Solicitare primită',confirmed:'Programare confirmată',in_progress:'În lucru',completed:'Lucrare finalizată',cancelled:'Anulată'};const date=row.updated_at?new Date(row.updated_at).toLocaleString('ro-RO'):'—';message('repair-lookup-result','Stare: '+(labels[row.status]||row.status)+' · Ultima actualizare: '+date,true);}catch(err){console.error(err);message('repair-lookup-result','Verificarea nu este disponibilă momentan. Dacă funcția nu a fost încă activată, revino mai târziu.');}});
 const reviews=document.getElementById('reviews-list');
 if(reviews) fetch(URL+'/rest/v1/reviews?select=customer_name,rating,review_text,created_at&approved=eq.true&order=created_at.desc&limit=12',{headers:{'apikey':KEY,'Authorization':'Bearer '+KEY}}).then(r=>{if(!r.ok)throw new Error('HTTP '+r.status);return r.json();}).then(rows=>{reviews.replaceChildren();if(!rows.length){const p=document.createElement('p');p.className='muted';p.textContent='Momentan nu există recenzii publicate. Poți fi primul care lasă o părere!';reviews.append(p);return;}rows.forEach(row=>{const card=document.createElement('article');card.className='review-card';const stars=document.createElement('div');stars.className='review-stars';stars.textContent='★'.repeat(row.rating)+'☆'.repeat(5-row.rating);const title=document.createElement('h3');title.textContent=row.customer_name;const body=document.createElement('p');body.textContent=row.review_text;card.append(stars,title,body);reviews.append(card);});}).catch(err=>{console.error(err);reviews.textContent='Recenziile nu pot fi încărcate momentan.';});
 const reviewForm=document.getElementById('review-form');
 if(reviewForm) reviewForm.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(reviewForm);message('review-result','Se trimite recenzia...');try{const r=await fetch(URL+'/rest/v1/reviews',{method:'POST',headers:{...headers,'Prefer':'return=minimal'},body:JSON.stringify({customer_name:String(d.get('name')).trim(),rating:Number(d.get('rating')),review_text:String(d.get('review')).trim(),approved:false})});if(!r.ok)throw new Error(await r.text());reviewForm.reset();message('review-result','Mulțumim! Recenzia a fost trimisă și va apărea după verificare.',true);}catch(err){console.error(err);message('review-result','Nu am putut trimite recenzia. Funcția poate necesita activarea tabelelor în Supabase.');}});
 const reminder=document.getElementById('reminder-form');
 if(reminder){const due=reminder.querySelector('[name="due_date"]');if(due){const d=new Date();due.min=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');}
 reminder.addEventListener('submit',async e=>{e.preventDefault();const d=new FormData(reminder);message('reminder-result','Se înregistrează solicitarea...');try{const r=await fetch(URL+'/rest/v1/maintenance_reminders',{method:'POST',headers:{...headers,'Prefer':'return=minimal'},body:JSON.stringify({customer_name:String(d.get('name')).trim(),phone:String(d.get('phone')).trim(),email:String(d.get('email')||'').trim()||null,vehicle:String(d.get('vehicle')).trim(),reminder_type:d.get('type'),due_date:d.get('due_date'),consent:d.get('consent')==='on'})});if(!r.ok)throw new Error(await r.text());reminder.reset();message('reminder-result','Solicitarea a fost înregistrată. Te vom contacta pentru detalii.',true);}catch(err){console.error(err);message('reminder-result','Nu am putut înregistra solicitarea. Funcția poate necesita activarea tabelelor în Supabase.');}});}
})();
